package com.collectiq.workflow;
import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.jdbc.core.JdbcTemplate;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Component public class CollectionScheduler{
 private static final Logger log=LoggerFactory.getLogger(CollectionScheduler.class);private final JdbcTemplate db;public CollectionScheduler(JdbcTemplate d){db=d;}
 @Scheduled(cron="${COLLECTION_CRON:0 0 9 * * *}",zone="${COLLECTION_TIMEZONE:Asia/Kolkata}")
 public void queueOverdue(){int n=db.update("insert into reminder_approvals(tenant_id,invoice_id,recipient,message,status) select i.tenant_id,i.id,c.phone,concat('Payment reminder: invoice ',i.invoice_number,' for INR ',i.amount,' was due ',i.due_date,'. Please share expected payment date. If already paid, please disregard.'),'PENDING' from invoices i join customers c on c.id=i.customer_id where i.status='OPEN' and i.due_date<current_date and c.phone is not null and not exists(select 1 from reminder_approvals a where a.invoice_id=i.id and a.status in ('PENDING','APPROVED'))");log.info("Daily scheduler queued {} reminders",n);}
 @Scheduled(fixedDelayString="${WORKFLOW_POLL_MS:15000}") @Transactional public void processQueuedRuns(){List<Map<String,Object>> runs=db.queryForList("select id,tenant_id from collection_runs where status='QUEUED' order by created_at limit 20");for(var run:runs){long id=((Number)run.get("id")).longValue();String tenant=Objects.toString(run.get("tenant_id"));try{db.update("update collection_runs set status='RUNNING',started_at=now() where id=? and status='QUEUED'",id);int n=db.update("insert into reminder_approvals(tenant_id,invoice_id,recipient,message,status) select i.tenant_id,i.id,c.phone,concat('Payment reminder: invoice ',i.invoice_number,' for INR ',i.amount,' was due ',i.due_date,'. Please share expected payment date. If already paid, please disregard.'),'PENDING' from invoices i join customers c on c.id=i.customer_id where i.tenant_id=? and i.status='OPEN' and i.due_date<current_date and c.phone is not null and not exists(select 1 from reminder_approvals a where a.invoice_id=i.id and a.status in ('PENDING','APPROVED'))",tenant);db.update("update collection_runs set status='COMPLETED',finished_at=now(),details=coalesce(details,'{}'::jsonb)||jsonb_build_object('remindersQueued',?) where id=?",n,id);}catch(Exception e){db.update("update collection_runs set status='FAILED',finished_at=now(),details=coalesce(details,'{}'::jsonb)||jsonb_build_object('error',?) where id=?",e.getClass().getSimpleName(),id);log.error("Workflow {} failed",id,e);}}}
}